# ============================================================
# OCTC NOTEBOOK-EQUIVALENT NAME STANDARDISATION
# Mirrors the name matching used in OCTC_PRODUCTION.ipynb:
# cleaned punctuation-insensitive key -> exact dictionary lookup.
# ============================================================
def _octc_clean_base_name(value):
    if pd.isna(value):
        return ""

    value = str(value)
    value = value.replace("\xa0", " ")
    value = re.sub(r"[\x00-\x1f\x7f-\x9f]", "", value)
    value = value.replace("\r", " ").replace("\n", " ")
    value = re.sub(r"\s+", " ", value)
    return value.strip()


def _octc_strip_punctuation(value):
    import unicodedata

    return "".join(
        character
        for character in value
        if not unicodedata.category(character).startswith("P")
    )


def _octc_name_match_key(value):
    value = _octc_clean_base_name(value)

    # Many rows in the name-variations file are stored as anchored regex
    # patterns, for example ^Chen Xiang Ang$ and ^Tan Tate$.
    # Unicode punctuation removal does NOT remove ^ or $ because Python
    # classifies them as symbols (Sk and Sc), not punctuation.  Without this
    # explicit cleanup the variation keys become ^chenxiangang$ / ^tantate$,
    # which cannot match the database keys chenxiangang / tantate.
    value = value.replace("^", "").replace("$", "").replace("\\", "")

    value = _octc_strip_punctuation(value)
    value = re.sub(r"\s+", "", value)
    return value.casefold()


def _octc_clean_replacement_name(value):
    value = _octc_clean_base_name(value)
    value = _octc_strip_punctuation(value)
    value = re.sub(r"\s+", " ", value)
    return value.strip().casefold()


def standardize_octc_names_like_notebook(df_input, names_input):
    """Return a copy with NAME standardised exactly like the OCTC notebook."""
    df_output = df_input.copy()
    names_reference = names_input.copy()

    if "NAME" not in df_output.columns:
        return df_output

    required_reference_cols = {"VARIATION", "NAME"}
    if not required_reference_cols.issubset(names_reference.columns):
        df_output["NAME"] = (
            df_output["NAME"]
            .apply(_octc_clean_replacement_name)
            .str.title()
        )
        return df_output

    df_output["NAME_KEY"] = df_output["NAME"].apply(_octc_name_match_key)

    names_reference["VARIATION_KEY"] = (
        names_reference["VARIATION"].apply(_octc_name_match_key)
    )
    names_reference["NAME_CLEAN"] = (
        names_reference["NAME"].apply(_octc_clean_replacement_name)
    )

    # The notebook keeps the last row for a duplicated variation key.
    name_map = (
        names_reference
        .loc[names_reference["VARIATION_KEY"].astype(str).str.strip() != ""]
        .drop_duplicates(subset=["VARIATION_KEY"], keep="last")
        .set_index("VARIATION_KEY")["NAME_CLEAN"]
        .to_dict()
    )

    df_output["NAME"] = df_output["NAME_KEY"].map(name_map).fillna(
        df_output["NAME"].apply(_octc_clean_replacement_name)
    )
    df_output["NAME"] = df_output["NAME"].str.title()

    return df_output.drop(columns=["NAME_KEY"])

# ============================================================
# END OCTC NOTEBOOK-EQUIVALENT NAME STANDARDISATION
# ============================================================


# ============================================================
# OCTC DELTA REPORT HELPERS
# OCTC_DELTA_PATCH_VERSION: 2026-08-21-v3-stable-athlete-identity
# ------------------------------------------------------------
# The normal OCTC report below remains unchanged.  These helpers rebuild the
# same OCTC selection pipeline for any chosen report end date so two snapshots
# can be compared without relying on previously exported files.
# ============================================================
def _octc_delta_canonical_name_key(value):
    """Stable OCTC athlete identity based on the already-canonicalised name.

    Do NOT switch between UID and name across report dates: UIDs can be blank in
    an earlier result and populated in a later result, which would make the same
    athlete appear to be two different identities.
    """
    return _octc_name_match_key(value)


def prepare_octc_delta_base(data_input, benchmarks_input, current_report_end_date):
    """Prepare OCTC rows once through the later delta report date.

    Expensive row-level work (result conversion, benchmark merge and name
    standardisation) is independent of the snapshot date, so it is performed
    once. Each snapshot still filters this prepared data to its own report date
    BEFORE best-result selection, tier assignment and Rule E ranking.
    """
    start_date_delta = pd.Timestamp('2025-01-01')
    octc_cutoff_delta = pd.Timestamp('2026-12-31')
    current_end_date_delta = min(
        pd.Timestamp(current_report_end_date),
        octc_cutoff_delta,
    )

    parsed_dates = pd.to_datetime(
        data_input['DATE'],
        format='mixed',
        dayfirst=False,
        utc=True,
        errors='coerce',
    ).dt.tz_localize(None)

    current_mask = (
        (parsed_dates >= start_date_delta)
        & (parsed_dates <= current_end_date_delta)
    )

    athletes_selected_delta = data_input.loc[current_mask].copy()
    athletes_selected_delta['DATE'] = parsed_dates.loc[current_mask]

    benchmark_delta = benchmarks_input.loc[
        benchmarks_input['BENCHMARK_COMPETITION'] == '2025 SEAG Bronze'
    ].copy()

    df_delta = pd.merge(
        left=athletes_selected_delta,
        right=benchmark_delta,
        how='left',
        left_on=['MAPPED_EVENT', 'GENDER'],
        right_on=['EVENT', 'GENDER'],
    )

    clean_columns(df_delta)

    df_delta['RESULT'] = df_delta['RESULT'].replace(regex=r'–', value=np.nan)
    df_delta['RESULT'] = df_delta['RESULT'].apply(
        normalize_excel_track_time_for_selection
    )

    process_results(df_delta)

    df_delta['PERF_SCALAR'] = (
        df_delta['Delta5'] / df_delta['STANDARDISED_BENCHMARK'] * 100
    )

    # Load and apply the name-variation reference once for both snapshots.
    names_for_delta = name_variations().copy()
    df_delta = standardize_octc_names_like_notebook(
        df_delta,
        names_for_delta,
    )

    allowed_nationalities = ['SGP', 'SIN', 'NONE', '']
    df_local_delta = df_delta.loc[
        df_delta['NATIONALITY']
        .fillna('')
        .astype(str)
        .str.strip()
        .str.upper()
        .isin(allowed_nationalities)
    ].copy()

    df_local_delta['PERF_SCALAR'] = pd.to_numeric(
        df_local_delta['PERF_SCALAR'],
        errors='coerce',
    )

    # clean_columns()/process_results() can leave DATE as an Arrow/string
    # column. Re-normalise it here after all shared preprocessing so every
    # snapshot comparison uses a true pandas datetime dtype.
    df_local_delta['DATE'] = pd.to_datetime(
        df_local_delta['DATE'],
        format='mixed',
        dayfirst=False,
        utc=True,
        errors='coerce',
    ).dt.tz_localize(None)
    df_local_delta = df_local_delta.loc[df_local_delta['DATE'].notna()].copy()

    # Establish one stable athlete identity BEFORE either snapshot chooses a
    # best result. Names have already been canonicalised above, and the same
    # cleaned canonical-name key is used for both dates. This prevents name
    # variants or a UID appearing only in the later period from splitting one
    # athlete into multiple identities.
    df_local_delta['ATHLETE_KEY'] = (
        df_local_delta['NAME']
        .apply(_octc_delta_canonical_name_key)
        .fillna('')
        .astype(str)
        .str.strip()
    )
    df_local_delta = df_local_delta.loc[
        df_local_delta['ATHLETE_KEY'].ne('')
    ].copy()

    return df_local_delta.reset_index(drop=True)


def build_octc_snapshot_for_delta(prepared_delta_base, report_end_date):
    """Build one OCTC Rule E snapshot from the once-prepared delta base.

    The date filter happens before best-result selection, tiering and Rule E,
    so later results cannot influence an earlier snapshot.
    """
    octc_cutoff_delta = pd.Timestamp('2026-12-31')
    end_date_delta = min(pd.Timestamp(report_end_date), octc_cutoff_delta)

    # Defensive conversion in case a cached/older prepared dataframe carries
    # DATE as string/Arrow string. This prevents str-vs-Timestamp comparisons.
    snapshot_dates = pd.to_datetime(
        prepared_delta_base['DATE'],
        format='mixed',
        dayfirst=False,
        utc=True,
        errors='coerce',
    ).dt.tz_localize(None)

    df_local_delta = prepared_delta_base.loc[
        snapshot_dates.notna() & (snapshot_dates <= end_date_delta)
    ].copy()
    df_local_delta['DATE'] = snapshot_dates.loc[df_local_delta.index]

    finite_mask_delta = np.isfinite(df_local_delta['PERF_SCALAR'])
    df_best_candidates_delta = df_local_delta.loc[
        finite_mask_delta
    ].copy()

    # Rebuild ATHLETE_KEY defensively in case Streamlit serves an older cached
    # prepared dataframe. The key is canonical-name based and deliberately does
    # not depend on UID availability.
    if 'ATHLETE_KEY' not in df_best_candidates_delta.columns:
        df_best_candidates_delta['ATHLETE_KEY'] = (
            df_best_candidates_delta['NAME']
            .apply(_octc_delta_canonical_name_key)
        )
    else:
        missing_identity = (
            df_best_candidates_delta['ATHLETE_KEY']
            .fillna('')
            .astype(str)
            .str.strip()
            .eq('')
        )
        if missing_identity.any():
            df_best_candidates_delta.loc[missing_identity, 'ATHLETE_KEY'] = (
                df_best_candidates_delta.loc[missing_identity, 'NAME']
                .apply(_octc_delta_canonical_name_key)
            )

    for grouping_col in ['NAME', 'MAPPED_EVENT', 'GENDER', 'ATHLETE_KEY']:
        df_best_candidates_delta[grouping_col] = (
            df_best_candidates_delta[grouping_col]
            .fillna('')
            .astype(str)
            .str.strip()
        )

    df_best_candidates_delta = df_best_candidates_delta.loc[
        df_best_candidates_delta['ATHLETE_KEY'].ne('')
        & df_best_candidates_delta['MAPPED_EVENT'].ne('')
    ].copy()

    # Pick exactly one best performance for each athlete / gender / event
    # INSIDE this snapshot. PERF_SCALAR is constructed so larger is always
    # better for both timed and field events. DATE descending is only a
    # deterministic tie-breaker when the same best performance occurs twice.
    top_performers_delta = (
        df_best_candidates_delta
        .sort_values(
            ['MAPPED_EVENT', 'GENDER', 'ATHLETE_KEY', 'PERF_SCALAR', 'DATE'],
            ascending=[True, True, True, False, False],
        )
        .drop_duplicates(
            subset=['MAPPED_EVENT', 'GENDER', 'ATHLETE_KEY'],
            keep='first',
        )
        .reset_index(drop=True)
    )

    top_performers_delta['TIER'] = np.where(
        top_performers_delta['Delta_Benchmark'] >= 0,
        'Tier 1',
        np.where(
            (top_performers_delta['Delta_Benchmark'] < 0)
            & (top_performers_delta['Delta2'] >= 0),
            'Tier 2',
            np.where(
                (top_performers_delta['Delta2'] < 0)
                & (top_performers_delta['Delta3.5'] >= 0),
                'Tier 3',
                np.where(
                    (top_performers_delta['Delta3.5'] < 0)
                    & (top_performers_delta['Delta5'] >= 0),
                    'Tier 4',
                    ' ',
                ),
            ),
        ),
    )

    required_snapshot_cols = [
        'NAME', 'COMPETITION_RANK', 'TEAM', 'RESULT', 'WIND', 'EVENT_x',
        'DIVISION', 'STAGE', 'AGE', 'GENDER', 'ATHLETE_KEY', 'UNIQUE_ID', 'NATIONALITY',
        'DICT_RESULTS', 'DATE', 'YEAR', 'COMPETITION', 'DOB',
        'CATEGORY_EVENT', 'REGION', 'SOURCE', 'REMARKS', 'SUB_EVENT',
        'DISTANCE', 'MAPPED_EVENT', 'BENCHMARK_COMPETITION',
        'RESULT_BENCHMARK', 'STANDARDISED_BENCHMARK', '2%', '3.50%', '5%',
        '10%', 'RESULT_CONV', 'Delta2', 'Delta3.5', 'Delta5', 'Delta10',
        'Delta_Benchmark', 'PERF_SCALAR', 'TIER',
    ]

    for col in required_snapshot_cols:
        if col not in top_performers_delta.columns:
            top_performers_delta[col] = np.nan

    df_no_na_delta = top_performers_delta.loc[
        top_performers_delta['STANDARDISED_BENCHMARK'].notna(),
        required_snapshot_cols,
    ].copy()

    final_tiered_delta = df_no_na_delta.loc[
        df_no_na_delta['TIER'] != ' '
    ].copy()

    all_ranking_delta = final_tiered_delta.sort_values(
        ['MAPPED_EVENT', 'GENDER', 'PERF_SCALAR'],
        ascending=[False, False, False],
    ).copy()

    all_ranking_delta['Rank'] = (
        all_ranking_delta
        .groupby(['GENDER', 'MAPPED_EVENT', 'TIER'])
        .cumcount()
        + 1
    )

    all_ranking_delta['TIER_ADJ'] = np.where(
        (all_ranking_delta['TIER'] == 'Tier 1')
        & (all_ranking_delta['Rank'] >= 3),
        'Tier 2',
        np.where(
            (all_ranking_delta['TIER'] == 'Tier 2')
            & (all_ranking_delta['Rank'] >= 3),
            'Tier 3',
            np.where(
                (all_ranking_delta['TIER'] == 'Tier 3')
                & (all_ranking_delta['Rank'] >= 3),
                'Tier 4',
                all_ranking_delta['TIER'],
            ),
        ),
    )

    rerank_delta = all_ranking_delta.sort_values(
        ['MAPPED_EVENT', 'GENDER', 'TIER_ADJ', 'PERF_SCALAR'],
        ascending=[False, False, False, False],
    ).copy()

    rerank_delta['Rank_ADJ'] = (
        rerank_delta
        .groupby(['MAPPED_EVENT', 'GENDER', 'TIER_ADJ'])
        .cumcount()
        + 1
    )

    return rerank_delta.reset_index(drop=True)


def _octc_delta_athlete_key(row):
    """Stable athlete/event key shared by every delta snapshot.

    Use the cleaned canonical name for identity on BOTH dates. UNIQUE_ID remains
    useful output metadata but is not allowed to change the matching key,
    because an athlete can have a blank UID in an older result and a populated
    UID in a newer result.
    """
    athlete_name_key = row.get('ATHLETE_KEY', '')
    athlete_name_key = (
        '' if pd.isna(athlete_name_key) else str(athlete_name_key).strip()
    )
    if not athlete_name_key:
        athlete_name_key = _octc_delta_canonical_name_key(row.get('NAME', ''))

    gender_key = str(row.get('GENDER', '')).strip().casefold()
    event_key = str(row.get('MAPPED_EVENT', '')).strip().casefold()
    return 'NAME:' + athlete_name_key + '|' + gender_key + '|' + event_key


def compare_octc_snapshots(previous_snapshot, current_snapshot):
    """Return new OCTC entries and adjusted-tier upgrades between snapshots."""
    previous = previous_snapshot.copy()
    current = current_snapshot.copy()

    tier_order = {
        'Tier 1': 1,
        'Tier 2': 2,
        'Tier 3': 3,
        'Tier 4': 4,
    }
    visible_tiers = {'Tier 1', 'Tier 2', 'Tier 3'}

    if previous.empty:
        previous = pd.DataFrame(columns=current.columns)
    if current.empty:
        return pd.DataFrame()

    # Recreate ATHLETE_KEY defensively for snapshots made by an older cached
    # helper, then build the same name-based event key on both dates.
    for snapshot in [previous, current]:
        if 'ATHLETE_KEY' not in snapshot.columns:
            snapshot['ATHLETE_KEY'] = snapshot['NAME'].apply(
                _octc_delta_canonical_name_key
            )
        else:
            snapshot['ATHLETE_KEY'] = snapshot['ATHLETE_KEY'].fillna('').astype(str)
            missing_identity = snapshot['ATHLETE_KEY'].str.strip().eq('')
            if missing_identity.any():
                snapshot.loc[missing_identity, 'ATHLETE_KEY'] = (
                    snapshot.loc[missing_identity, 'NAME']
                    .apply(_octc_delta_canonical_name_key)
                )

    previous['DELTA_KEY'] = previous.apply(_octc_delta_athlete_key, axis=1)
    current['DELTA_KEY'] = current.apply(_octc_delta_athlete_key, axis=1)

    # build_octc_snapshot_for_delta() should already guarantee one row per
    # athlete/gender/event. If an old cached snapshot still contains duplicates,
    # resolve them by actual performance (not by lexical Tier order / row order).
    def _dedupe_delta_snapshot(snapshot):
        if snapshot.empty or not snapshot['DELTA_KEY'].duplicated(keep=False).any():
            return snapshot

        snapshot = snapshot.copy()
        snapshot['_DELTA_PERF_SORT'] = pd.to_numeric(
            snapshot.get('PERF_SCALAR'), errors='coerce'
        )
        snapshot['_DELTA_DATE_SORT'] = pd.to_datetime(
            snapshot.get('DATE'), errors='coerce', utc=True
        )
        snapshot = (
            snapshot
            .sort_values(
                ['DELTA_KEY', '_DELTA_PERF_SORT', '_DELTA_DATE_SORT'],
                ascending=[True, False, False],
            )
            .drop_duplicates(subset=['DELTA_KEY'], keep='first')
            .drop(columns=['_DELTA_PERF_SORT', '_DELTA_DATE_SORT'])
            .reset_index(drop=True)
        )
        return snapshot

    previous = _dedupe_delta_snapshot(previous)
    current = _dedupe_delta_snapshot(current)

    # Current delta candidates must be visible in the normal OCTC report.
    current = current.loc[
        current['TIER_ADJ'].isin(visible_tiers)
    ].copy()

    previous_by_key = previous.set_index(
        'DELTA_KEY', drop=False, verify_integrity=True
    )

    previous_visible_athletes = set(
        previous.loc[
            previous['TIER_ADJ'].isin(visible_tiers),
            'ATHLETE_KEY',
        ]
        .fillna('')
        .astype(str)
        .str.strip()
    )

    rows = []

    for _, current_row in current.iterrows():
        delta_key = current_row['DELTA_KEY']
        current_tier = str(current_row.get('TIER_ADJ', '')).strip()
        current_tier_num = tier_order.get(current_tier)

        previous_row = None
        if delta_key in previous_by_key.index:
            previous_row = previous_by_key.loc[delta_key]

        if previous_row is None:
            current_athlete_key = str(
                current_row.get('ATHLETE_KEY', '')
            ).strip()
            change_type = (
                'NEW EVENT ENTRY'
                if current_athlete_key in previous_visible_athletes
                else 'NEW NAME'
            )
            previous_tier = ''
            previous_rank = np.nan
            previous_result = ''
            previous_date = pd.NaT
            previous_competition = ''
        else:
            previous_tier = str(previous_row.get('TIER_ADJ', '')).strip()
            previous_tier_num = tier_order.get(previous_tier)

            if (
                previous_tier_num is None
                or current_tier_num is None
                or current_tier_num >= previous_tier_num
            ):
                continue

            change_type = 'TIER UPGRADE'
            previous_rank = previous_row.get('Rank_ADJ', np.nan)
            previous_result = previous_row.get('RESULT', '')
            previous_date = previous_row.get('DATE', pd.NaT)
            previous_competition = previous_row.get('COMPETITION', '')

        rows.append({
            'CHANGE': change_type,
            'NAME': current_row.get('NAME', ''),
            'GENDER': current_row.get('GENDER', ''),
            'EVENT': current_row.get('MAPPED_EVENT', ''),
            'PREVIOUS_TIER': previous_tier,
            'CURRENT_TIER': current_tier,
            'PREVIOUS_RANK': previous_rank,
            'CURRENT_RANK': current_row.get('Rank_ADJ', np.nan),
            'PREVIOUS_RESULT': previous_result,
            'CURRENT_RESULT': current_row.get('RESULT', ''),
            'PREVIOUS_RESULT_DATE': previous_date,
            'CURRENT_RESULT_DATE': current_row.get('DATE', pd.NaT),
            'PREVIOUS_COMPETITION': previous_competition,
            'CURRENT_COMPETITION': current_row.get('COMPETITION', ''),
            'UNIQUE_ID': current_row.get('UNIQUE_ID', ''),
        })

    delta_report = pd.DataFrame(rows)
    if delta_report.empty:
        return delta_report

    for date_col in ['PREVIOUS_RESULT_DATE', 'CURRENT_RESULT_DATE']:
        date_values = pd.to_datetime(delta_report[date_col], errors='coerce')
        delta_report[date_col] = np.where(
            date_values.notna(),
            date_values.dt.strftime('%Y-%m-%d'),
            '',
        )

    change_order = {
        'NEW NAME': 1,
        'NEW EVENT ENTRY': 2,
        'TIER UPGRADE': 3,
    }
    delta_report['_CHANGE_ORDER'] = delta_report['CHANGE'].map(change_order).fillna(99)
    delta_report['_CURRENT_TIER_ORDER'] = delta_report['CURRENT_TIER'].map(tier_order).fillna(99)

    delta_report = (
        delta_report
        .sort_values(
            ['_CHANGE_ORDER', '_CURRENT_TIER_ORDER', 'EVENT', 'GENDER', 'NAME'],
            ascending=[True, True, True, True, True],
        )
        .drop(columns=['_CHANGE_ORDER', '_CURRENT_TIER_ORDER'])
        .reset_index(drop=True)
    )

    return delta_report

