def filter_report_date_range(df_input, start_date, end_date):
    """Return rows whose DATE falls within the inclusive selected date range.

    DATE values in PRODUCTION may arrive as strings, timezone-aware timestamps,
    or pandas datetimes.  Normalising to UTC here keeps all standalone report
    date controls consistent without changing the underlying SQL per selection.
    """
    df = df_input.copy()

    if 'DATE' not in df.columns:
        return df.iloc[0:0].copy()

    parsed_dates = pd.to_datetime(
        df['DATE'],
        format='mixed',
        dayfirst=False,
        utc=True,
        errors='coerce',
    )

    start_ts = pd.Timestamp(start_date, tz='UTC')
    # Use an exclusive next-day bound so all timestamps on the selected end date
    # are included, regardless of their time of day.
    end_exclusive = pd.Timestamp(end_date, tz='UTC') + pd.Timedelta(days=1)

    mask = (
        parsed_dates.notna()
        & (parsed_dates >= start_ts)
        & (parsed_dates < end_exclusive)
    )

    # Preserve the existing standalone-report convention of a timezone-naive
    # DATE column after filtering, while using UTC-aware values for the mask.
    df['DATE'] = parsed_dates.dt.tz_localize(None)
    return df.loc[mask].copy()



def filter_jumps_calendar_date_range(df_input, start_date, end_date):
    """Return Jumps rows whose calendar DATE is inside the inclusive range.

    Jumps programme/selection eligibility is defined by competition calendar date,
    not time-of-day. The source DATE column is deliberately left unchanged for
    audit purposes; only a temporary parsed calendar-date Series is used for the
    filter.
    """
    df = df_input.copy()

    if 'DATE' not in df.columns:
        return df.iloc[0:0].copy()

    parsed_dates = pd.to_datetime(
        df['DATE'],
        format='mixed',
        dayfirst=False,
        utc=True,
        errors='coerce',
    )
    calendar_dates = parsed_dates.dt.date

    start_date = pd.Timestamp(start_date).date()
    end_date = pd.Timestamp(end_date).date()

    mask = (
        calendar_dates.notna()
        & (calendar_dates >= start_date)
        & (calendar_dates <= end_date)
    )
    return df.loc[mask].copy()


def summarize_jumps_data_checkpoint(df_input, checkpoint):
    """Return compact date/year diagnostics for a Jumps report pipeline checkpoint."""
    if df_input is None:
        df = pd.DataFrame()
    else:
        df = df_input.copy()

    if 'DATE' in df.columns:
        parsed_dates = pd.to_datetime(
            df['DATE'],
            format='mixed',
            dayfirst=False,
            utc=True,
            errors='coerce',
        )
    else:
        parsed_dates = pd.Series(pd.NaT, index=df.index, dtype='datetime64[ns, UTC]')

    valid_dates = parsed_dates.dropna()
    year_counts = (
        valid_dates.dt.year
        .value_counts()
        .sort_index()
        .rename_axis('YEAR')
        .reset_index(name='ROWS')
    )
    if not year_counts.empty:
        year_counts['YEAR'] = year_counts['YEAR'].astype(int)

    summary = {
        'CHECKPOINT': checkpoint,
        'ROWS': int(len(df)),
        'VALID_DATE_ROWS': int(parsed_dates.notna().sum()),
        'INVALID_DATE_ROWS': int(parsed_dates.isna().sum()),
        'MIN_DATE': valid_dates.min().date().isoformat() if not valid_dates.empty else '',
        'MAX_DATE': valid_dates.max().date().isoformat() if not valid_dates.empty else '',
        'ROWS_2025': int((parsed_dates.dt.year == 2025).sum()),
        'ROWS_2026': int((parsed_dates.dt.year == 2026).sum()),
    }

    return summary, year_counts


