def validate_jumps_programme_benchmark_order():
    """Fail fast if any National benchmark is not above Training."""
    benchmarks = get_jumps_selection_benchmarks().copy()
    pivot = benchmarks.pivot_table(
        index=['EVENT', 'GENDER'],
        columns='SQUAD',
        values='BENCHMARK',
        aggfunc='first',
    )

    required = {'TRAINING', 'NATIONAL'}
    missing = required.difference(set(pivot.columns))
    if missing:
        raise ValueError(
            'Jumps Programme benchmark configuration is incomplete: missing '
            + ', '.join(sorted(missing))
        )

    invalid = pivot.loc[
        pivot['NATIONAL'].isna()
        | pivot['TRAINING'].isna()
        | (pivot['NATIONAL'] <= pivot['TRAINING'])
    ]
    if not invalid.empty:
        invalid_pairs = [
            f'{event} / {gender}'
            for event, gender in invalid.index.tolist()
        ]
        raise ValueError(
            'Jumps Programme benchmark configuration is invalid. National must '
            'be strictly higher than Training for: ' + ', '.join(invalid_pairs)
        )

    return True


def _jumps_result_to_numeric(value):
    """Convert a field-event result such as 6.80m / 6.80 / 6.80w to metres."""
    if pd.isna(value):
        return np.nan

    value = str(value).strip()
    if value.upper() in {'', 'NM', '-', 'DNS', 'DNF', 'DNQ', 'DQ', 'FOUL', 'NH'}:
        return np.nan

    # Wind legality is evaluated explicitly below from BOTH the raw RESULT suffix
    # and the WIND column. Strip suffixes here only so the mark remains
    # numeric and visible/auditable even when it is ineligible for selection.
    value = re.sub(r'(?i)GR', '', value)
    value = re.sub(r'(?i)[mw]$', '', value)
    value = value.strip()

    try:
        return round(float(value), 2)
    except Exception:
        return np.nan


def build_jumps_selection(df_input, squad):
    """Build a Training or National jumps selection from one shared pipeline.

    Illegal-wind Long Jump / Triple Jump results remain in the processed audit
    dataframe but are excluded from best-performance selection and tiering.
    """
    squad = str(squad).strip().upper()
    if squad not in {'TRAINING', 'NATIONAL'}:
        raise ValueError("squad must be 'TRAINING' or 'NATIONAL'")

    df = df_input.copy()

    required_cols = [
        'NAME', 'RESULT', 'TEAM', 'AGE', 'COMPETITION_RANK', 'DIVISION',
        'EVENT', 'DISTANCE', 'EVENT_CLASS', 'UNIQUE_ID', 'DOB', 'NATIONALITY',
        'WIND', 'CATEGORY_EVENT', 'GENDER', 'COMPETITION', 'DATE', 'YEAR', 'REGION',
    ]
    for col in required_cols:
        if col not in df.columns:
            df[col] = ''

    # Preserve native numeric/date dtypes and clean text columns only.
    text_cols = df.select_dtypes(include=['object', 'string']).columns
    for col in text_cols:
        df[col] = (
            df[col]
            .fillna('')
            .astype(str)
            .str.replace('\xa0', ' ', regex=False)
            .str.replace(r'[\x00-\x1f\x7f-\x9f]', '', regex=True)
            .str.replace('\r', ' ', regex=False)
            .str.replace('\n', ' ', regex=False)
            .str.strip()
        )

    # Use the same cleaned-key canonicalisation as the OCTC / notebook flow.
    names_for_jumps = name_variations().copy()
    df = standardize_octc_names_like_notebook(df, names_for_jumps)

    # Singapore athletes only.
    allowed_nationalities = {'SGP', 'SIN', 'NONE', ''}
    nationality_key = (
        df['NATIONALITY']
        .fillna('')
        .astype(str)
        .str.strip()
        .str.upper()
    )
    df = df.loc[nationality_key.isin(allowed_nationalities)].copy()

    # Pole Vault is intentionally excluded from this report.
    jump_events = {'Long Jump', 'Triple Jump', 'High Jump'}
    df = df.loc[df['EVENT'].isin(jump_events)].copy()

    df['RESULT_CONV'] = df['RESULT'].apply(_jumps_result_to_numeric)

    # Wind legality applies only to horizontal jumps. Unknown/blank wind remains
    # eligible (agreed Option A behaviour), but explicit source labels such as
    # "Illegal" must be treated as illegal rather than falling through to Unknown.
    horizontal_jumps = {'Long Jump', 'Triple Jump'}

    # A trailing ``w`` in the raw RESULT is itself an explicit illegal-wind
    # marker in the source data (for example ``6.96w``).  Preserve the numeric
    # mark via _jumps_result_to_numeric(), but exclude it from qualification.
    result_text = (
        df['RESULT']
        .fillna('')
        .astype(str)
        .str.strip()
    )
    result_has_w = result_text.str.contains(
        r'w\s*$',
        case=False,
        regex=True,
        na=False,
    )

    wind_text = (
        df['WIND']
        .fillna('')
        .astype(str)
        .str.strip()
    )
    wind_key = (
        wind_text
        .str.casefold()
        .str.replace(r'\s+', ' ', regex=True)
    )

    df['WIND_NUM'] = pd.to_numeric(
        wind_text.str.replace('+', '', regex=False),
        errors='coerce',
    )

    horizontal_mask = df['EVENT'].isin(horizontal_jumps)

    # Explicit non-numeric source labels that mean the mark is illegal.
    # Keep this intentionally narrow so values such as blank/NWI remain Unknown.
    explicit_illegal_wind = wind_key.isin({
        'illegal',
        'illegal wind',
    })

    numeric_illegal_wind = (
        df['WIND_NUM'].notna()
        & (df['WIND_NUM'] > 2.0)
    )

    result_w_illegal = horizontal_mask & result_has_w
    explicit_label_illegal = horizontal_mask & explicit_illegal_wind
    numeric_limit_illegal = horizontal_mask & numeric_illegal_wind

    df['ILLEGAL_WIND'] = (
        result_w_illegal | explicit_label_illegal | numeric_limit_illegal
    )

    # Keep all applicable exclusion reasons for audit.
    df['ILLEGAL_WIND_REASON'] = ''
    for reason_mask, reason_label in [
        (result_w_illegal, 'RESULT ends in w'),
        (explicit_label_illegal, 'WIND explicitly marked Illegal'),
        (numeric_limit_illegal, 'Numeric wind > +2.0'),
    ]:
        existing = df.loc[reason_mask, 'ILLEGAL_WIND_REASON']
        df.loc[reason_mask, 'ILLEGAL_WIND_REASON'] = np.where(
            existing.eq(''),
            reason_label,
            existing + '; ' + reason_label,
        )

    df['WIND_STATUS'] = 'Not applicable'

    # Unknown applies only where the horizontal-jump wind cannot be parsed and
    # neither RESULT nor WIND explicitly marks the attempt as illegal. These
    # genuinely unknown-wind results remain eligible by design.
    df.loc[
        horizontal_mask
        & df['WIND_NUM'].isna()
        & ~result_has_w
        & ~explicit_illegal_wind,
        'WIND_STATUS',
    ] = 'Unknown'

    df.loc[
        horizontal_mask
        & df['WIND_NUM'].notna()
        & ~df['ILLEGAL_WIND'],
        'WIND_STATUS',
    ] = 'Legal'

    df.loc[df['ILLEGAL_WIND'], 'WIND_STATUS'] = 'Illegal wind'
    df['RESULT_ELIGIBLE'] = ~df['ILLEGAL_WIND']

    benchmarks = get_jumps_selection_benchmarks()
    benchmarks = benchmarks.loc[benchmarks['SQUAD'] == squad].copy()

    df = df.merge(
        benchmarks,
        how='left',
        on=['EVENT', 'GENDER'],
    )

    numeric_cols = ['RESULT_CONV', 'BENCHMARK', '2%', '3.5%', '5%', '10%']
    for col in numeric_cols:
        df[col] = pd.to_numeric(df[col], errors='coerce')

    df['Delta2'] = df['RESULT_CONV'] - df['2%']
    df['Delta3.5'] = df['RESULT_CONV'] - df['3.5%']
    df['Delta5'] = df['RESULT_CONV'] - df['5%']
    df['Delta10'] = df['RESULT_CONV'] - df['10%']
    df['Delta_Benchmark'] = df['RESULT_CONV'] - df['BENCHMARK']
    df['PERF_SCALAR'] = df['Delta5'] / df['BENCHMARK'] * 100

    # Preserve all processed rows for the audit table; only eligible results may
    # become the selected best result.
    finite_mask = np.isfinite(pd.to_numeric(df['PERF_SCALAR'], errors='coerce'))
    eligible_mask = finite_mask & df['RESULT_ELIGIBLE'] & df['BENCHMARK'].notna()
    df_best_candidates = df.loc[eligible_mask].copy()

    top_performers = (
        df_best_candidates
        .sort_values(
            ['EVENT', 'GENDER', 'NAME', 'PERF_SCALAR'],
            ascending=[True, True, True, False],
        )
        .drop_duplicates(
            subset=['EVENT', 'GENDER', 'NAME'],
            keep='first',
        )
        .reset_index(drop=True)
    )

    top_performers['TIER'] = np.select(
        [
            top_performers['Delta_Benchmark'] >= 0,
            top_performers['Delta2'] >= 0,
            top_performers['Delta3.5'] >= 0,
            top_performers['Delta5'] >= 0,
            top_performers['Delta10'] >= 0,
        ],
        ['Tier 1', 'Tier 2', 'Tier 3', 'Tier 4', 'Tier 5'],
        default='',
    )

    final_selection = (
        top_performers
        .loc[top_performers['TIER'] != '']
        .sort_values(
            ['EVENT', 'GENDER', 'PERF_SCALAR'],
            ascending=[True, True, False],
        )
        .reset_index(drop=True)
    )

    final_selection['MAPPED_EVENT'] = final_selection['EVENT']
    df['MAPPED_EVENT'] = df['EVENT']

    return final_selection, df



