# Configurable historical lookback used by Jumps Programme Changes.
# Override in Streamlit secrets when the programme cycle changes, e.g.:
# JUMPS_PROGRAMME_LOOKBACK_START = "2025-01-01"
JUMPS_PROGRAMME_LOOKBACK_START_DEFAULT = datetime.date(2025, 1, 1)


def get_jumps_programme_lookback_start():
    """Return configured Programme Changes lookback start, defaulting to 2025-01-01."""
    default_value = JUMPS_PROGRAMME_LOOKBACK_START_DEFAULT

    try:
        configured_value = st.secrets.get(
            'JUMPS_PROGRAMME_LOOKBACK_START',
            default_value.isoformat(),
        )
    except Exception:
        # Keep local/notebook execution safe when Streamlit secrets are unavailable.
        configured_value = default_value.isoformat()

    parsed = pd.to_datetime(configured_value, errors='coerce')
    if pd.isna(parsed):
        return default_value

    return parsed.date()


def _jumps_programme_name_signature(value):
    """Order-insensitive token signature used only for the explicit spex list."""
    value = _octc_clean_base_name(value).casefold()
    tokens = re.findall(r"[a-z0-9]+", value)
    return "|".join(sorted(tokens))


def _jumps_programme_excluded_identity_sets():
    """Return canonical keys and token signatures for the spex exclusion list.

    The exclusion names are first passed through the same name-variation mapping
    as result rows.  An order-insensitive signature is also retained as a narrow
    fallback for the explicit exclusion list, so name-order variants are excluded
    even if a particular variation is missing from the GCS mapping.
    """
    raw_excluded = pd.DataFrame({'NAME': JUMPS_PROGRAMME_EXCLUDED_NAMES})
    canonical_excluded = standardize_octc_names_like_notebook(
        raw_excluded,
        name_variations().copy(),
    )

    excluded_keys = set(
        canonical_excluded['NAME']
        .apply(_octc_name_match_key)
        .fillna('')
        .astype(str)
        .str.strip()
        .loc[lambda s: s.ne('')]
        .tolist()
    )

    # Include signatures from both the supplied names and their canonicalised
    # versions.  This fallback is deliberately limited to the 12 explicit spex
    # exclusions and is not used for general athlete identity matching.
    excluded_signatures = {
        _jumps_programme_name_signature(name)
        for name in JUMPS_PROGRAMME_EXCLUDED_NAMES
        if _jumps_programme_name_signature(name)
    }
    excluded_signatures.update(
        {
            _jumps_programme_name_signature(name)
            for name in canonical_excluded['NAME'].tolist()
            if _jumps_programme_name_signature(name)
        }
    )

    return excluded_keys, excluded_signatures


def _prepare_jumps_programme_identity(df_input):
    """Add stable athlete/event keys and remove programme-excluded athletes."""
    df = df_input.copy()
    if df.empty:
        return df

    for col in ['NAME', 'GENDER', 'EVENT']:
        if col not in df.columns:
            df[col] = ''

    df['ATHLETE_KEY'] = (
        df['NAME']
        .apply(_octc_name_match_key)
        .fillna('')
        .astype(str)
        .str.strip()
    )
    df['GENDER_KEY'] = (
        df['GENDER'].fillna('').astype(str).str.strip().str.casefold()
    )
    df['EVENT_KEY'] = (
        df['EVENT'].fillna('').astype(str).str.strip().str.casefold()
    )

    excluded_keys, excluded_signatures = _jumps_programme_excluded_identity_sets()
    df['NAME_SIGNATURE'] = df['NAME'].apply(_jumps_programme_name_signature)
    df = df.loc[
        df['ATHLETE_KEY'].ne('')
        & ~df['ATHLETE_KEY'].isin(excluded_keys)
        & ~df['NAME_SIGNATURE'].isin(excluded_signatures)
    ].copy()

    df['PROGRAMME_KEY'] = (
        df['ATHLETE_KEY'] + '|' + df['GENDER_KEY'] + '|' + df['EVENT_KEY']
    )
    return df


def build_jumps_programme_snapshot(df_input, report_end_date, lookback_start=None):
    """Build one cumulative Jumps Programme snapshot through report_end_date.

    The snapshot includes results from the configurable historical lookback start
    through report_end_date. Status precedence is National > Training > Not
    Selected. A squad status requires the athlete's best legal/eligible mark to
    meet that squad's actual benchmark (Tier 1). Tier 2-5 remain monitoring bands
    in the standalone selection reports and do not by themselves establish
    programme membership.
    """
    if lookback_start is None:
        lookback_start = get_jumps_programme_lookback_start()

    # Eligibility is based on calendar date only; retain the source timestamp.
    df_period = filter_jumps_calendar_date_range(
        df_input,
        lookback_start,
        report_end_date,
    )

    if df_period.empty:
        return pd.DataFrame()

    validate_jumps_programme_benchmark_order()

    training_selection, _ = build_jumps_selection(df_period, squad='TRAINING')
    national_selection, _ = build_jumps_selection(df_period, squad='NATIONAL')

    # 'Met the benchmark standard' means the actual benchmark has been reached.
    # In the existing Tier 1-5 engine, that corresponds exactly to Tier 1.
    training_met = training_selection.loc[
        training_selection['TIER'].eq('Tier 1')
    ].copy()
    national_met = national_selection.loc[
        national_selection['TIER'].eq('Tier 1')
    ].copy()

    training_met = _prepare_jumps_programme_identity(training_met)
    national_met = _prepare_jumps_programme_identity(national_met)

    if not national_met.empty:
        national_met['PROGRAMME_STATUS'] = 'National'
    if not training_met.empty:
        training_met['PROGRAMME_STATUS'] = 'Training'

    national_keys = set(
        national_met.get('PROGRAMME_KEY', pd.Series(dtype='object')).tolist()
    )

    # National status takes precedence because the National benchmark is the
    # higher squad standard.  A National athlete also meets the Training
    # standard but should appear only once in the snapshot.
    if not training_met.empty:
        training_only = training_met.loc[
            ~training_met['PROGRAMME_KEY'].isin(national_keys)
        ].copy()
    else:
        training_only = training_met.copy()

    snapshot = pd.concat(
        [national_met, training_only],
        ignore_index=True,
        sort=False,
    )

    if snapshot.empty:
        return snapshot

    # Defensive uniqueness: the selection engine should already have one best
    # row per athlete/gender/event, but preserve the best mark if duplicates
    # ever appear upstream.
    snapshot['RESULT_CONV'] = pd.to_numeric(
        snapshot.get('RESULT_CONV'), errors='coerce'
    )
    snapshot = (
        snapshot
        .sort_values(
            ['PROGRAMME_KEY', 'RESULT_CONV', 'DATE'],
            ascending=[True, False, False],
        )
        .drop_duplicates(subset=['PROGRAMME_KEY'], keep='first')
        .reset_index(drop=True)
    )
    return snapshot


def _jumps_programme_date_text(value):
    parsed = pd.to_datetime(value, errors='coerce')
    if pd.isna(parsed):
        return ''
    return parsed.strftime('%Y-%m-%d')


def _jumps_programme_value(row, column, default=''):
    if row is None or column not in row.index:
        return default
    value = row[column]
    if pd.isna(value):
        return default
    return value


def compare_jumps_programme_snapshots(previous_snapshot, current_snapshot):
    """Return only NEW ENTRY and Training -> National UPGRADE transitions."""
    previous = previous_snapshot.copy()
    current = current_snapshot.copy()

    output_columns = [
        'CHANGE', 'NAME', 'GENDER', 'EVENT',
        'PREVIOUS_STATUS', 'CURRENT_STATUS',
        'PREVIOUS_RESULT', 'CURRENT_RESULT',
        'PREVIOUS_WIND', 'CURRENT_WIND',
        'PREVIOUS_WIND_STATUS', 'CURRENT_WIND_STATUS',
        'PREVIOUS_BENCHMARK', 'CURRENT_BENCHMARK',
        'PREVIOUS_RESULT_DATE', 'CURRENT_RESULT_DATE',
        'PREVIOUS_COMPETITION', 'CURRENT_COMPETITION',
        'UNIQUE_ID',
    ]

    if current.empty:
        return pd.DataFrame(columns=output_columns)

    if previous.empty:
        previous_by_key = {}
    else:
        previous_by_key = {
            row['PROGRAMME_KEY']: row
            for _, row in previous.iterrows()
        }

    rows = []
    for _, current_row in current.iterrows():
        key = current_row.get('PROGRAMME_KEY', '')
        previous_row = previous_by_key.get(key)

        previous_status = (
            'Not Selected' if previous_row is None
            else str(_jumps_programme_value(previous_row, 'PROGRAMME_STATUS', '')).strip()
        )
        current_status = str(
            _jumps_programme_value(current_row, 'PROGRAMME_STATUS', '')
        ).strip()

        if previous_row is None:
            change = 'NEW ENTRY'
        elif previous_status == 'Training' and current_status == 'National':
            change = 'UPGRADE'
        else:
            # Same-squad improvements, continued membership and any downgrade
            # are outside the requested Programme Changes report.
            continue

        unique_id = str(
            _jumps_programme_value(current_row, 'UNIQUE_ID', '')
        ).strip()
        if unique_id == '' and previous_row is not None:
            unique_id = str(
                _jumps_programme_value(previous_row, 'UNIQUE_ID', '')
            ).strip()

        rows.append(
            {
                'CHANGE': change,
                'NAME': _jumps_programme_value(current_row, 'NAME', ''),
                'GENDER': _jumps_programme_value(current_row, 'GENDER', ''),
                'EVENT': _jumps_programme_value(current_row, 'EVENT', ''),
                'PREVIOUS_STATUS': previous_status,
                'CURRENT_STATUS': current_status,
                'PREVIOUS_RESULT': _jumps_programme_value(previous_row, 'RESULT', ''),
                'CURRENT_RESULT': _jumps_programme_value(current_row, 'RESULT', ''),
                'PREVIOUS_WIND': _jumps_programme_value(previous_row, 'WIND', ''),
                'CURRENT_WIND': _jumps_programme_value(current_row, 'WIND', ''),
                'PREVIOUS_WIND_STATUS': _jumps_programme_value(previous_row, 'WIND_STATUS', ''),
                'CURRENT_WIND_STATUS': _jumps_programme_value(current_row, 'WIND_STATUS', ''),
                'PREVIOUS_BENCHMARK': _jumps_programme_value(previous_row, 'BENCHMARK', ''),
                'CURRENT_BENCHMARK': _jumps_programme_value(current_row, 'BENCHMARK', ''),
                'PREVIOUS_RESULT_DATE': _jumps_programme_date_text(
                    _jumps_programme_value(previous_row, 'DATE', '')
                ),
                'CURRENT_RESULT_DATE': _jumps_programme_date_text(
                    _jumps_programme_value(current_row, 'DATE', '')
                ),
                'PREVIOUS_COMPETITION': _jumps_programme_value(previous_row, 'COMPETITION', ''),
                'CURRENT_COMPETITION': _jumps_programme_value(current_row, 'COMPETITION', ''),
                'UNIQUE_ID': unique_id,
            }
        )

    result = pd.DataFrame(rows, columns=output_columns)
    if result.empty:
        return result

    change_order = pd.Categorical(
        result['CHANGE'],
        categories=['UPGRADE', 'NEW ENTRY'],
        ordered=True,
    )
    result = (
        result
        .assign(_CHANGE_ORDER=change_order)
        .sort_values(
            ['_CHANGE_ORDER', 'EVENT', 'GENDER', 'NAME'],
            ascending=[True, True, True, True],
        )
        .drop(columns=['_CHANGE_ORDER'])
        .reset_index(drop=True)
    )
    return result


def build_jumps_programme_verification(previous_snapshot, current_snapshot):
    """Build audit tables proving the Training -> National intersection.

    Returns four dataframes:
      1. athlete-events classified as Training in the earlier snapshot;
      2. athlete-events classified as National in the later snapshot;
      3. the exact PROGRAMME_KEY intersection of those two populations; and
      4. current-snapshot keys absent from the earlier snapshot (NEW ENTRY audit).
    """
    previous = previous_snapshot.copy()
    current = current_snapshot.copy()

    if previous.empty:
        previous_training = previous.copy()
    else:
        previous_training = previous.loc[
            previous['PROGRAMME_STATUS'].eq('Training')
        ].copy()

    if current.empty:
        current_national = current.copy()
    else:
        current_national = current.loc[
            current['PROGRAMME_STATUS'].eq('National')
        ].copy()

    previous_keys = set(
        previous.get('PROGRAMME_KEY', pd.Series(dtype='object')).dropna().tolist()
    )
    if current.empty:
        current_new_entries = current.copy()
    else:
        current_new_entries = current.loc[
            ~current['PROGRAMME_KEY'].isin(previous_keys)
        ].copy()

    audit_base_cols = [
        'PROGRAMME_KEY', 'NAME', 'GENDER', 'EVENT', 'PROGRAMME_STATUS',
        'RESULT', 'WIND', 'WIND_STATUS', 'BENCHMARK', 'DATE', 'COMPETITION',
        'UNIQUE_ID',
    ]

    def _audit_view(frame):
        if frame.empty:
            return pd.DataFrame(columns=audit_base_cols)
        cols = [col for col in audit_base_cols if col in frame.columns]
        result = frame.loc[:, cols].copy()
        if 'DATE' in result.columns:
            result['DATE'] = pd.to_datetime(result['DATE'], errors='coerce').dt.strftime('%Y-%m-%d')
        if 'BENCHMARK' in result.columns:
            result['BENCHMARK'] = pd.to_numeric(result['BENCHMARK'], errors='coerce').round(3)
        return result.reset_index(drop=True)

    previous_training_view = _audit_view(previous_training)
    current_national_view = _audit_view(current_national)
    current_new_entries_view = _audit_view(current_new_entries)

    if previous_training.empty or current_national.empty:
        upgrades = pd.DataFrame(columns=[
            'NAME', 'GENDER', 'EVENT',
            'PREVIOUS_RESULT', 'CURRENT_RESULT',
            'PREVIOUS_WIND', 'CURRENT_WIND',
            'PREVIOUS_BENCHMARK', 'CURRENT_BENCHMARK',
            'PREVIOUS_RESULT_DATE', 'CURRENT_RESULT_DATE',
            'PREVIOUS_COMPETITION', 'CURRENT_COMPETITION',
            'UNIQUE_ID',
        ])
    else:
        previous_cols = [
            'PROGRAMME_KEY', 'NAME', 'GENDER', 'EVENT', 'RESULT', 'WIND',
            'BENCHMARK', 'DATE', 'COMPETITION', 'UNIQUE_ID',
        ]
        current_cols = previous_cols.copy()
        prev = previous_training.loc[:, [c for c in previous_cols if c in previous_training.columns]].copy()
        curr = current_national.loc[:, [c for c in current_cols if c in current_national.columns]].copy()

        upgrades = prev.merge(
            curr,
            on='PROGRAMME_KEY',
            how='inner',
            suffixes=('_PREVIOUS', '_CURRENT'),
        )

        if upgrades.empty:
            upgrades = pd.DataFrame(columns=[
                'NAME', 'GENDER', 'EVENT',
                'PREVIOUS_RESULT', 'CURRENT_RESULT',
                'PREVIOUS_WIND', 'CURRENT_WIND',
                'PREVIOUS_BENCHMARK', 'CURRENT_BENCHMARK',
                'PREVIOUS_RESULT_DATE', 'CURRENT_RESULT_DATE',
                'PREVIOUS_COMPETITION', 'CURRENT_COMPETITION',
                'UNIQUE_ID',
            ])
        else:
            # Use the later-snapshot display identity, falling back to the earlier one.
            upgrades_out = pd.DataFrame({
                'NAME': upgrades.get('NAME_CURRENT', upgrades.get('NAME_PREVIOUS', '')),
                'GENDER': upgrades.get('GENDER_CURRENT', upgrades.get('GENDER_PREVIOUS', '')),
                'EVENT': upgrades.get('EVENT_CURRENT', upgrades.get('EVENT_PREVIOUS', '')),
                'PREVIOUS_RESULT': upgrades.get('RESULT_PREVIOUS', ''),
                'CURRENT_RESULT': upgrades.get('RESULT_CURRENT', ''),
                'PREVIOUS_WIND': upgrades.get('WIND_PREVIOUS', ''),
                'CURRENT_WIND': upgrades.get('WIND_CURRENT', ''),
                'PREVIOUS_BENCHMARK': upgrades.get('BENCHMARK_PREVIOUS', ''),
                'CURRENT_BENCHMARK': upgrades.get('BENCHMARK_CURRENT', ''),
                'PREVIOUS_RESULT_DATE': upgrades.get('DATE_PREVIOUS', ''),
                'CURRENT_RESULT_DATE': upgrades.get('DATE_CURRENT', ''),
                'PREVIOUS_COMPETITION': upgrades.get('COMPETITION_PREVIOUS', ''),
                'CURRENT_COMPETITION': upgrades.get('COMPETITION_CURRENT', ''),
                'UNIQUE_ID': upgrades.get('UNIQUE_ID_CURRENT', upgrades.get('UNIQUE_ID_PREVIOUS', '')),
            })

            for col in ['PREVIOUS_RESULT_DATE', 'CURRENT_RESULT_DATE']:
                upgrades_out[col] = pd.to_datetime(
                    upgrades_out[col], errors='coerce'
                ).dt.strftime('%Y-%m-%d')
            for col in ['PREVIOUS_BENCHMARK', 'CURRENT_BENCHMARK']:
                upgrades_out[col] = pd.to_numeric(
                    upgrades_out[col], errors='coerce'
                ).round(3)

            upgrades = upgrades_out.sort_values(
                ['EVENT', 'GENDER', 'NAME'],
                ascending=[True, True, True],
            ).reset_index(drop=True)

    return {
        'previous_training': previous_training_view,
        'current_national': current_national_view,
        'training_to_national': upgrades,
        'new_entries': current_new_entries_view,
    }

def build_jumps_programme_illegal_wind_audit(df_input, start_date, end_date):
    """Return Programme-scope horizontal-jump rows excluded for illegal wind."""
    audit_cols = [
        'NAME', 'GENDER', 'EVENT', 'RESULT', 'RESULT_CONV', 'WIND', 'WIND_NUM',
        'WIND_STATUS', 'ILLEGAL_WIND_REASON', 'DATE', 'COMPETITION', 'UNIQUE_ID',
    ]

    df_period = filter_jumps_calendar_date_range(df_input, start_date, end_date)
    if df_period.empty:
        return pd.DataFrame(columns=audit_cols)

    # Wind legality is squad-independent; use TRAINING only to invoke the shared
    # preprocessing engine and obtain the complete processed audit dataframe.
    _, processed = build_jumps_selection(df_period, squad='TRAINING')
    illegal = processed.loc[processed['ILLEGAL_WIND']].copy()

    # Match the Programme Changes population by applying the same event-specific
    # canonical identity and explicit spex exclusions.
    illegal = _prepare_jumps_programme_identity(illegal)
    if illegal.empty:
        return pd.DataFrame(columns=audit_cols)

    cols = [col for col in audit_cols if col in illegal.columns]
    audit = illegal.loc[:, cols].copy()
    if 'DATE' in audit.columns:
        audit['DATE'] = pd.to_datetime(
            audit['DATE'], format='mixed', errors='coerce'
        ).dt.strftime('%Y-%m-%d')
    if 'RESULT_CONV' in audit.columns:
        audit['RESULT_CONV'] = pd.to_numeric(
            audit['RESULT_CONV'], errors='coerce'
        ).round(3)
    if 'WIND_NUM' in audit.columns:
        audit['WIND_NUM'] = pd.to_numeric(
            audit['WIND_NUM'], errors='coerce'
        ).round(3)

    sort_cols = [
        col for col in ['DATE', 'EVENT', 'GENDER', 'NAME']
        if col in audit.columns
    ]
    if sort_cols:
        ascending = [False] + [True] * (len(sort_cols) - 1)
        audit = audit.sort_values(sort_cols, ascending=ascending)
    return audit.reset_index(drop=True)


def _is_calendar_month_end(value):
    value = pd.Timestamp(value).date()
    return (value + datetime.timedelta(days=1)).month != value.month


def _latest_completed_month_end(reference_date=None):
    """Return the most recent month-end on or before reference_date."""
    if reference_date is None:
        reference_date = datetime.date.today()
    reference_date = pd.Timestamp(reference_date).date()
    if _is_calendar_month_end(reference_date):
        return reference_date
    return reference_date.replace(day=1) - datetime.timedelta(days=1)


def _previous_month_end(month_end_date):
    month_end_date = pd.Timestamp(month_end_date).date()
    return month_end_date.replace(day=1) - datetime.timedelta(days=1)


