@st.cache_data(ttl=20000)
def fetch_all_data():   # for database access

    all_data = client.query_and_wait(all_sql).to_dataframe()
 #   all_data = clean_columns(all_data)

    all_data=simple_map_events(all_data)


    # Casefold for consistency
    all_data['NAME'] = all_data['NAME'].str.casefold()

    # Standardize DATE column → always YYYY-MM-DD string
    all_data['DATE'] = pd.to_datetime(all_data['DATE'], errors='coerce') # NEW

    if pd.api.types.is_datetime64tz_dtype(all_data['DATE']): #NEW
        all_data['DATE'] = all_data['DATE'].dt.tz_localize(None)  #NEW

    # Convert to YYYY-MM-DD string
    all_data['DATE'] = all_data['DATE'].dt.strftime("%Y-%m-%d")

    # Load name variations lazily only when database records are actually requested.
    names = gspread_names()

    # Work on a copy of names
    n = names[['VARIATION', 'NAME']].dropna().copy()
    n['VARIATION'] = n['VARIATION'].str.strip().str.casefold()

    # Remove ^ and $ anchors
    n['VARIATION'] = n['VARIATION'].str.replace(r'^\^', '', regex=True)
    n['VARIATION'] = n['VARIATION'].str.replace(r'\$$', '', regex=True)

    n['NAME'] = n['NAME'].str.casefold()

    # Drop duplicates → required for mapping
    mapping = n.drop_duplicates(subset='VARIATION').set_index('VARIATION')['NAME']

    # Vectorized replacement
    all_data['NAME'] = all_data['NAME'].map(mapping).fillna(all_data['NAME'])


 #   all_data = all_data[['NAME', 'DATE', 'MAPPED_EVENT', 'COMPETITION', 'RESULT', 'WIND', 'HOST_CITY', 'AGE', 'GENDER', 'EVENT_CLASS', 'DOB']]


    # RESOURCE PATCH:
    # Do not convert every result in the full database here.
    # RESULT_CONV / RESULT_FLOAT are calculated later only on the selected subset
    # inside format_results_like_search(), List Results, or Performance Trend Graphs.
    # This removes a full-table apply() on every cache refresh.
    all_data['STATUS'] = ''
    all_data['RESULT_CONV'] = np.nan

    return all_data


# ============================================================
# SEARCH OUTPUT FORMATTER PATCH
# Used by "Search Database Records by Name or Competition"
# ============================================================

# ============================================================
# OCTC EXCEL TRACK-TIME NORMALISATION
# The notebook normalises Excel-imported track times such as
# 00:14:57.400000 to 14:57.40 before converting them to seconds.
# Without this step, older versions of convert_time_refactored() may
# fail on the two-colon Excel representation, causing the record to
# receive a blank RESULT_CONV and be removed by the finite-value filter.
# ============================================================
def normalize_excel_track_time_for_selection(value):
    """Normalise Excel-style track times for the selection pipeline.

    Examples
    --------
    00:14:57.400000 -> 14:57.40
    00:17:06.700000 -> 17:06.70
    00:04:05.090000 -> 4:05.09

    Times with a non-zero hour component are left unchanged so road-race
    and marathon durations continue to be interpreted as hours.
    """
    if pd.isna(value):
        return value

    value_text = str(value).strip()

    match = re.fullmatch(
        r"00:(?P<minutes>\d{1,2}):(?P<seconds>\d{2})(?:\.(?P<fraction>\d+))?",
        value_text,
    )

    if not match:
        return value

    minutes = int(match.group("minutes"))
    seconds = int(match.group("seconds"))
    fraction = match.group("fraction") or "0"

    # Keep centiseconds to match the notebook/report convention.
    centiseconds = fraction[:2].ljust(2, "0")
    return f"{minutes}:{seconds:02d}.{centiseconds}"


