def parse_performance_seconds(value):
    """
    Convert a performance value into seconds where possible.

    Handles:
    - numeric seconds: 10.2 -> 10.2
    - Excel/time strings: 00:11:25.210000 -> 685.21
    - mm:ss strings: 11:25.210000 -> 685.21
    - pandas Timedelta-like strings: 0 days 00:11:25.210000 -> 685.21

    Returns np.nan if the value cannot be interpreted as a numeric mark/time.
    """
    if pd.isna(value):
        return np.nan

    # pandas Timedelta / datetime-like objects
    if isinstance(value, pd.Timedelta):
        return value.total_seconds()

    # Excel time values may sometimes arrive as datetime/time-like objects.
    # Use only the time component.
    if hasattr(value, 'hour') and hasattr(value, 'minute') and hasattr(value, 'second'):
        try:
            microsecond = getattr(value, 'microsecond', 0)
            return (
                float(value.hour) * 3600
                + float(value.minute) * 60
                + float(value.second)
                + float(microsecond) / 1_000_000
            )
        except Exception:
            pass

    s = str(value).strip()

    if s == '' or s.lower() in {'nan', 'none', 'nat', 'null', '<na>'}:
        return np.nan

    # Remove obvious whitespace noise
    s = re.sub(r'\s+', ' ', s)

    # pandas Timedelta string, e.g. "0 days 00:11:25.210000"
    m = re.fullmatch(
        r'(?:(?P<days>\d+)\s+days?\s+)?(?P<hours>\d{1,3}):(?P<minutes>\d{2}):(?P<seconds>\d{2}(?:\.\d+)?)',
        s,
    )
    if m:
        days = int(m.group('days') or 0)
        hours = int(m.group('hours'))
        minutes = int(m.group('minutes'))
        seconds = float(m.group('seconds'))
        return days * 86400 + hours * 3600 + minutes * 60 + seconds

    # mm:ss string, e.g. "11:25.210000"
    m = re.fullmatch(r'(?P<minutes>\d{1,3}):(?P<seconds>\d{2}(?:\.\d+)?)', s)
    if m:
        minutes = int(m.group('minutes'))
        seconds = float(m.group('seconds'))
        return minutes * 60 + seconds

    # Plain numeric value, usually seconds for timed events or metres for field events
    numeric_value = pd.to_numeric(s, errors='coerce')
    if pd.notna(numeric_value):
        return float(numeric_value)

    return np.nan


def format_seconds_no_leading_zeros(value):
    """
    Format seconds/time-like values for display without leading 00:00.

    Examples:
    - 10.2              -> 10.20
    - 00:00:10.20       -> 10.20
    - 00:11:25.210000   -> 11:25.21
    - 72.34             -> 1:12.34
    - 3723.45           -> 1:02:03.45
    """
    value = parse_performance_seconds(value)

    if pd.isna(value):
        return ''

    total_seconds = float(value)

    if total_seconds < 0:
        return ''

    hours = int(total_seconds // 3600)
    minutes = int((total_seconds % 3600) // 60)
    seconds = total_seconds - (hours * 3600) - (minutes * 60)

    if hours > 0:
        return f"{hours}:{minutes:02d}:{seconds:05.2f}"

    if minutes > 0:
        return f"{minutes}:{seconds:05.2f}"

    return f"{seconds:.2f}"


def format_numeric_two_dp(value):
    """Format numeric performance marks to two decimal places."""
    value = pd.to_numeric(value, errors='coerce')

    if pd.isna(value):
        return ''

    return f"{float(value):.2f}"


def format_road_race_duration(value):
    """Format marathon / half-marathon durations for ranking reports.

    Examples:
    - 00:11:25.210000 -> 11:25.21
    - 01:08:30        -> 1:08:30
    - 02:34:57.123456 -> 2:34:57.12
    """
    seconds = parse_performance_seconds(value)

    if pd.isna(seconds):
        return ''

    seconds = float(seconds)

    if seconds < 0:
        return ''

    hours = int(seconds // 3600)
    minutes = int((seconds % 3600) // 60)
    sec = seconds - (hours * 3600) - (minutes * 60)
    sec_is_whole = abs(sec - round(sec)) < 0.005

    if hours > 0:
        if sec_is_whole:
            return f"{hours}:{minutes:02d}:{int(round(sec)):02d}"
        return f"{hours}:{minutes:02d}:{sec:05.2f}"

    if minutes > 0:
        return f"{minutes}:{sec:05.2f}"

    return f"{sec:.2f}"

def format_results_like_search(df_input, include_result_conv=False, extra_cols=None):
    """
    Format database search results before display.

    This extracts the repeated formatting logic previously embedded in the
    Athlete Name and Competition Name search branches.

    Parameters
    ----------
    df_input : pandas.DataFrame
        Search results to format.
    include_result_conv : bool, default False
        If True, include RESULT_CONV in the output to preserve the old
        Competition Name display layout.
    extra_cols : list[str] or None, default None
        Optional extra columns to append after the standard display columns.
        Useful for benchmark reports where TIER / benchmark fields should be retained.

    Returns
    -------
    pandas.DataFrame
        Display-ready dataframe for Mito/spreadsheet().
    """

    df_search = df_input.copy()

    # --------------------------------------------------------
    # Ensure required columns exist
    # --------------------------------------------------------
    required_cols = [
        'NAME', 'DATE', 'MAPPED_EVENT', 'COMPETITION', 'RESULT',
        'STATUS', 'STAGE', 'WIND', 'HOST_CITY', 'AGE',
        'GENDER', 'EVENT_CLASS', 'DOB', 'RESULT_CONV'
    ]

    for col in required_cols:
        if col not in df_search.columns:
            df_search[col] = ''

    # --------------------------------------------------------
    # Event groups
    # --------------------------------------------------------
    distance_events = [
        '60m', '60m Hurdles', '80m', '100m', '100m Hurdles',
        '110m Hurdles', '400m Hurdles', '200m', '200m Hurdles',
        '300m', '400m', '800m', '10,000m', '2400m', '3000m',
        '5000m', '3000m Steeplechase', '1500m', '10000m Racewalk',
        '10,000m Racewalk', '5000m Racewalk', '5km Racewalk',
        '20km Racewalk', '1 Mile', '4 x 100m', '4 x 400m',
        '2000m Steeplechase', 'Marathon', 'Half Marathon',
        'Sprint Medley Relay'
    ]

    field_events = [
        'Javelin Throw', 'Pole Vault', 'Hammer Throw', 'Triple Jump',
        'Long Jump', 'Long Jump (Zone)', 'High Jump', 'Shot Put',
        'Discus Throw', 'Discus', 'Decathlon', 'Heptathlon'
    ]

    invalid_results = {
        '—', 'NONE', 'DQ', 'SCR', 'FS', 'DNQ', 'DNS', 'NH', 'NM',
        'FOUL', 'DNF', 'SR', '', ' '
    }

    # --------------------------------------------------------
    # Illegal wind handling
    # If RESULT contains 'w' and WIND is blank, set WIND to Illegal
    # --------------------------------------------------------
    mask_result_has_w = df_search['RESULT'].astype(str).str.contains(
        'w',
        case=False,
        na=False
    )

    mask_wind_is_missing = (
        df_search['WIND'].isna()
        | (df_search['WIND'].astype(str).str.strip() == '')
        | (df_search['WIND'].astype(str).str.lower().str.strip().isin(['nan', 'none', '-']))
    )

    df_search.loc[mask_result_has_w & mask_wind_is_missing, 'WIND'] = 'Illegal'

    # --------------------------------------------------------
    # Build numeric RESULT_FLOAT
    # Prefer RESULT_CONV if already present, otherwise calculate.
    # --------------------------------------------------------
    df_search['RESULT_FLOAT'] = df_search['RESULT_CONV'].apply(parse_performance_seconds)

    def convert_for_row(row):
        raw_result = str(row.get('RESULT', '')).strip()

        if raw_result.upper() in invalid_results:
            return np.nan

        # First handle Excel/time-like strings such as 00:11:25.210000.
        parsed_result = parse_performance_seconds(raw_result)
        if pd.notna(parsed_result):
            return parsed_result

        try:
            return convert_time_refactored(
                row.name,
                row.get('MAPPED_EVENT', ''),
                row.get('RESULT', '')
            )
        except Exception:
            return np.nan

    missing_result_float = df_search['RESULT_FLOAT'].isna()

    if missing_result_float.any():
        # The row converter can return blanks/strings for invalid or unparseable
        # results. Convert the replacement Series to numeric before assigning
        # into RESULT_FLOAT, otherwise pandas/Arrow can reject string values
        # being assigned into a float column.
        converted_values = df_search.loc[missing_result_float].apply(convert_for_row, axis=1)
        converted_values = pd.to_numeric(converted_values, errors='coerce')
        df_search.loc[missing_result_float, 'RESULT_FLOAT'] = converted_values

    df_search['RESULT_FLOAT'] = pd.to_numeric(df_search['RESULT_FLOAT'], errors='coerce')

    # Keep RESULT_CONV available for the old Competition Name layout
    df_search['RESULT_CONV'] = df_search['RESULT_FLOAT']

    # --------------------------------------------------------
    # Build RESULT_C
    # --------------------------------------------------------
    df_search['RESULT_C'] = pd.Series(index=df_search.index, dtype='object')

    mask_distance = df_search['MAPPED_EVENT'].isin(distance_events)
    mask_field = df_search['MAPPED_EVENT'].isin(field_events)

    # Timed events: display formatted time without leading 00:00
    # Example: 00:00:10.20 -> 10.20
    df_search.loc[mask_distance, 'RESULT_C'] = (
        df_search.loc[mask_distance, 'RESULT_FLOAT'].apply(format_seconds_no_leading_zeros)
    )

    # Field events: display metric mark to two decimal places
    df_search.loc[mask_field, 'RESULT_C'] = (
        df_search.loc[mask_field, 'RESULT_FLOAT'].apply(format_numeric_two_dp)
    )

    # Non-numeric / status results
    result_upper = df_search['RESULT'].astype(str).str.strip().str.upper()
    mask_non_numeric = result_upper.isin(invalid_results)

    df_search.loc[mask_non_numeric, 'RESULT_C'] = df_search.loc[mask_non_numeric, 'RESULT']

    # Fill anything still blank with original RESULT
    mask_result_c_blank = (
        df_search['RESULT_C'].isna()
        | (df_search['RESULT_C'].astype(str).str.strip() == '')
        | (df_search['RESULT_C'].astype(str).str.lower().str.strip() == 'nan')
    )

    df_search.loc[mask_result_c_blank, 'RESULT_C'] = df_search.loc[mask_result_c_blank, 'RESULT']

    # STATUS handling
    df_search['STATUS'] = df_search['STATUS'].fillna('').astype(str)
    df_search.loc[mask_non_numeric, 'STATUS'] = df_search.loc[mask_non_numeric, 'RESULT'].astype(str)

    # --------------------------------------------------------
    # Date formatting
    # --------------------------------------------------------
    date_converted = pd.to_datetime(df_search['DATE'], errors='coerce')

    try:
        if pd.api.types.is_datetime64tz_dtype(date_converted):
            date_converted = date_converted.dt.tz_convert(None)
    except Exception:
        pass

    df_search['DATE'] = np.where(
        date_converted.notna(),
        date_converted.dt.strftime('%Y-%m-%d'),
        df_search['DATE'].astype(str)
    )

    # --------------------------------------------------------
    # Final display columns
    # --------------------------------------------------------
    if include_result_conv:
        output_cols = [
            'NAME', 'DATE', 'MAPPED_EVENT', 'COMPETITION', 'RESULT_C',
            'RESULT_CONV', 'WIND', 'HOST_CITY', 'AGE', 'GENDER',
            'EVENT_CLASS', 'DOB'
        ]
    else:
        output_cols = [
            'NAME', 'DATE', 'MAPPED_EVENT', 'COMPETITION', 'RESULT_C',
            'STATUS', 'STAGE', 'WIND', 'HOST_CITY', 'AGE', 'GENDER',
            'EVENT_CLASS', 'DOB'
        ]

    if extra_cols is not None:
        extra_cols = [
            col for col in extra_cols
            if col in df_search.columns and col not in output_cols
        ]
        output_cols = output_cols + extra_cols

    df_final = df_search[output_cols].copy()
    df_final['NAME'] = df_final['NAME'].fillna('').astype(str).str.title()

    df_final = map_nwi(df_final)

    return df_final

